// Fire redacts values in an log Entry that match
// with keys defined in the RedactionList
func (h *Hook) Fire(e *logrus.Entry) error {
	if err := h.initRedaction(); err != nil {
		return err
	}
	for _, re := range h.redactionKeys {
		// Redact based on key matching in Data fields
		for k, v := range e.Data {
			if re.MatchString(k) {
				e.Data[k] = "[REDACTED]"
				continue
			}

			e.Data[k] = redactValue(v, re)
		}

		// Redact based on text matching in the Message field
		e.Message = re.ReplaceAllString(e.Message, "$1[REDACTED]$2")
	}

	return nil
}

func redactValue(value interface{}, re *regexp.Regexp) interface{} {
	if value == nil {
		return nil
	}
	if v, ok := value.(string); ok {
		return re.ReplaceAllString(v, "$1[REDACTED]$2")
	}
	v := reflect.ValueOf(value)
	if v.Kind() == reflect.Map {
		redacted := make(map[string]interface{}, v.Len())
		for _, key := range v.MapKeys() {
			name := fmt.Sprint(key.Interface())
			if re.MatchString(name) {
				redacted[name] = "[REDACTED]"
			} else {
				redacted[name] = redactValue(v.MapIndex(key).Interface(), re)
			}
		}
		return redacted
	}
	return re.ReplaceAllString(fmt.Sprintf("%v", value), "$1[REDACTED]$2")
}

